// pubspec.yaml:
//   scandit_flutter_datacapture_core: ^7.0.0
//   scandit_flutter_datacapture_barcode: ^7.0.0
import 'package:scandit_flutter_datacapture_core/scandit_flutter_datacapture_core.dart';
import 'package:scandit_flutter_datacapture_barcode/scandit_flutter_datacapture_barcode.dart';

class ScanScreen extends StatefulWidget {
  const ScanScreen({super.key});
  @override State<ScanScreen> createState() => _ScanScreenState();
}

class _ScanScreenState extends State<ScanScreen> implements BarcodeCaptureListener {
  late DataCaptureContext _ctx;
  late Camera _camera;
  late BarcodeCapture _capture;

  @override
  void initState() {
    super.initState();
    // 1. Context with license key (obtain from Scandit dashboard)
    _ctx = DataCaptureContext.forLicenseKey('YOUR_LICENSE_KEY');

    // 2. Camera (Scandit-managed; sets its own resolution optimally)
    _camera = Camera.defaultCamera!;
    _camera.applySettings(BarcodeCapture.recommendedCameraSettings);
    _ctx.setFrameSource(_camera);

    // 3. Barcode capture with settings
    final settings = BarcodeCaptureSettings()
      ..enableSymbologies({Symbology.qr, Symbology.ean13, Symbology.dataMatrix, Symbology.code128})
      ..codeDuplicateFilter = const Duration(milliseconds: 1500);
    _capture = BarcodeCapture.forContext(_ctx, settings);
    _capture.addListener(this);

    _camera.switchToDesiredState(FrameSourceState.on);
  }

  @override
  Future<void> didScan(BarcodeCapture mode, BarcodeCaptureSession session) async {
    final code = session.newlyRecognizedBarcodes.first;
    HapticFeedback.mediumImpact();
    if (mounted) Navigator.of(context).pop({'code': code.data, 'symbology': code.symbology.name});
  }

  @override
  Future<void> didUpdateSession(BarcodeCapture mode, BarcodeCaptureSession session) async {}

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Scan')),
      body: Stack(children: [
        DataCaptureView.forContext(_ctx)!,
        BarcodeCaptureOverlay.withBarcodeCapture(_capture),
      ]),
    );
  }

  @override
  void dispose() {
    _capture.removeListener(this);
    _camera.switchToDesiredState(FrameSourceState.off);
    super.dispose();
  }
}
